<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
const exportFolder=ref(''); const cfg=ref<any>(null),editor=ref(''),profiles=ref<string[]>([]),sizes=ref<string[]>([]),target=ref(''),useAuth=ref(false),history=ref<any[]>([]),job=ref<any>(null),auth=ref<any[]>([]),tab=ref('capture'),error=ref(''),busy=ref(false),zoom=ref('');let events:EventSource|undefined;
async function api(url:string,method='GET',body?:unknown){const res=await fetch('/api/'+url,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const v=await res.json();if(!res.ok)throw Error(v.error);return v}
async function action(fn:()=>Promise<void>){error.value='';busy.value=true;try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function reload(){history.value=await api('jobs');auth.value=await api('auth')}
onMounted(()=>action(async()=>{cfg.value=await api('config');editor.value=JSON.stringify(cfg.value,null,2);profiles.value=cfg.value.profiles.map((p:any)=>p.name);sizes.value=cfg.value.resolutions.map((r:any)=>r.name);await reload()}));
function watch(j:any){events?.close();job.value=j;if(['running','queued'].includes(j.status)){events=new EventSource('/api/jobs/'+j.id+'/events');events.onmessage=e=>{const v=JSON.parse(e.data);if(v){job.value=v;if(!['running','queued'].includes(v.status)){events?.close();void reload()}}};events.onerror=()=>{error.value='與本機服務連線中斷，請確認服務仍在執行';events?.close()}}}
async function start(){await action(async()=>{const j=await api('jobs','POST',{url:target.value,profiles:profiles.value,resolutions:sizes.value,useAuth:useAuth.value});watch(j)})}
const active=computed(()=>job.value&&['running','queued'].includes(job.value.status));const done=computed(()=>job.value?.items.filter((i:any)=>['完成','失敗','已取消'].includes(i.status)).length??0);
const image=(item:any)=>'/captures/'+job.value.id+'/'+item.file;
const label=(s:string)=>({running:'執行中',queued:'等待中',completed:'全部完成',partial:'部分失敗',cancelled:'已取消',failed:'執行失敗',interrupted:'服務曾中斷'}[s]??s);
function selectAll(){sizes.value=cfg.value.resolutions.map((r:any)=>r.name)}
function exportConfig(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([editor.value],{type:'application/json'}));a.download='screenshot.config.json';a.click();URL.revokeObjectURL(a.href)}
</script>
<template>
<header><div class="brand"><span class="logo">▣</span><div>RWD Capture<small>Chrome × Edge · 本機網頁截圖工作台</small></div></div><span class="local">● 本機執行 · 檔案保存在電腦</span></header>
<nav><button :class="{selected:tab==='capture'}" @click="tab='capture'">截圖工作台</button><button :class="{selected:tab==='history'}" @click="tab='history';action(reload)">歷史紀錄</button><button :class="{selected:tab==='settings'}" @click="tab='settings'">進階設定</button></nav>
<main><div v-if="error" role="alert" class="error">{{error}}</div>
<template v-if="cfg&&tab==='capture'"><section class="intro"><p class="eyebrow">RESPONSIVE SCREENSHOT STUDIO</p><h1>每個尺寸，都看清楚。</h1><p>一次擷取 Chrome 與 Edge，並排檢查你的響應式網頁。</p></section>
<div class="workspace"><aside><section class="card"><h2>01 · 網址與瀏覽器</h2><label>目標網址<input v-model="target" type="url" placeholder="https://example.com" /></label><div class="checks"><label v-for="p in cfg.profiles" :key="p.name"><input type="checkbox" v-model="profiles" :value="p.name" />{{p.name}}<small>{{p.browserExecutablePath?'指定 EXE':p.browserChannel||'Chromium'}}</small></label></div><label class="line"><input type="checkbox" v-model="useAuth" />使用已保存的登入狀態</label><p class="hint">不勾選即使用乾淨環境；登入狀態依瀏覽器分開保存。</p><template v-if="useAuth"><div v-for="a in auth" :key="a.name" class="auth"><b>{{a.name}}</b><small>{{a.saved?'已保存':'尚未登入'}}</small><button v-if="!a.open" :disabled="busy" @click="action(async()=>{await api('auth/'+a.name+'/open','POST',{url:target});await reload()})">開啟登入</button><button v-else :disabled="busy" @click="action(async()=>{await api('auth/'+a.name+'/save','POST');await reload()})">完成登入並保存</button><button :disabled="busy" @click="action(async()=>{await api('auth/'+a.name,'DELETE');await reload()})">清除</button></div><p class="hint">請先輸入網址，在各瀏覽器視窗完成登入後按保存。</p></template></section>
<section class="card"><h2>02 · 擷取尺寸 <button class="text" @click="selectAll">全選</button><button class="text" @click="sizes=[]">清空</button></h2><div class="size-list"><label v-for="r in cfg.resolutions" :key="r.name"><input type="checkbox" v-model="sizes" :value="r.name" /><span>{{r.name}}<small>{{r.width}} × {{r.height}} · {{r.deviceScaleFactor??1}}×</small></span></label></div><p class="hint">尺寸為 CSS viewport；圖片寬度會乘上裝置倍率。預設擷取整個頁面。</p><div class="total"><span>本次預計擷取</span><b>{{profiles.length*sizes.length}} 張</b></div><button class="primary full" :disabled="busy||active||!target||!profiles.length||!sizes.length" @click="start">開始擷取 →</button></section></aside>
<article><section v-if="!job" class="empty card"><div class="illustration">▤ ▤</div><h2>你的跨瀏覽器畫面，集中在這裡</h2><p>輸入網址並選擇尺寸，即可開始建立第一組截圖。</p><div class="badges"><span>全頁長圖</span><span>延遲圖片載入</span><span>雙瀏覽器並排</span></div></section>
<template v-else><section class="card progress"><div class="row"><h2>{{label(job.status)}}</h2><span>{{done}} / {{job.items.length}}</span></div><label v-if="!active">額外匯出資料夾（選填，完整路徑）<input v-model="exportFolder" placeholder="D:\Screenshots" /><button :disabled="busy||!exportFolder" @click="action(async()=>{const result=await api('jobs/'+job.id+'/export','POST',{folder:exportFolder});error='已匯出至 '+result.path})">匯出本批截圖與報告</button></label><progress :value="done" :max="job.items.length"></progress><p class="hint wrap">{{job.url}}</p><div class="row"><button v-if="active" @click="action(async()=>{await api('jobs/'+job.id+'/cancel','POST')})">取消工作</button><button v-if="!active&&job.items.some((i:any)=>i.status!=='完成')" @click="action(async()=>watch(await api('jobs/'+job.id+'/retry','POST')))">重試未完成項目</button><button @click="action(async()=>{await api('jobs/'+job.id+'/folder','POST')})">開啟輸出資料夾</button><a :href="'/captures/'+job.id+'/manifest.json'" target="_blank">執行報告 ↗</a></div></section>
<section v-for="r in job.config.resolutions" :key="r.name" class="result"><h3>{{r.name}} <small>{{r.width}} × {{r.height}}</small></h3><div class="compare" :style="{gridTemplateColumns:'repeat('+job.config.profiles.length+', minmax(0,1fr))'}"><div v-for="i in job.items.filter((i:any)=>i.resolution===r.name)" :key="i.profile" class="shot card"><div class="row"><b>{{i.profile}}</b><span :class="{'success':i.status==='完成'}">{{i.status}}</span></div><button v-if="i.file" class="preview" @click="zoom=image(i)"><img :width="i.meta?.imageWidth" :height="i.meta?.imageHeight" :src="image(i)" :alt="i.profile+' '+r.name+' 全頁截圖'" loading="lazy" /></button><div v-else class="placeholder">{{i.status==='等待中'?'等待擷取':i.status}}</div><small v-if="i.meta">實際圖片 {{i.meta.imageWidth}} × {{i.meta.imageHeight}} px</small><p class="error wrap" v-if="i.error">{{i.error}}</p><details v-if="i.warnings.length"><summary>{{i.warnings.length}} 項載入警告</summary><p v-for="w in i.warnings" class="hint wrap">{{w}}</p></details><a v-if="i.file" :href="image(i)" target="_blank">查看原圖 ↗</a></div></div></section></template></article></div></template>
<section v-if="tab==='history'"><h1>歷史紀錄</h1><p class="hint">每次執行獨立保存，先前截圖不會被覆寫。</p><div v-if="!history.length" class="card">尚無截圖紀錄。</div><button v-for="j in history" :key="j.id" class="history card" @click="watch(j);tab='capture'"><span>{{new Date(j.created).toLocaleString('zh-TW')}}<small>{{j.url}}</small></span><b>{{label(j.status)}} · {{j.items.length}} 張 →</b></button></section>
<section v-if="tab==='settings'" class="card settings"><h1>進階設定</h1><p>設定會儲存到 screenshot.config.json，執行中的工作仍使用開始時的設定。</p><label>擷取時顯示瀏覽器 <input type="checkbox" v-model="cfg.settings.headed" /></label><label>額外等待（毫秒）<input type="number" v-model.number="cfg.settings.extraWaitMs" min="0" max="60000" /></label><label>就緒元素 selector（選填）<input v-model="cfg.settings.readySelector" placeholder="#app .loaded" /></label><button @click="editor=JSON.stringify(cfg,null,2)">將上方選項更新到 JSON 編輯器</button><h2>完整 JSON 設定</h2><p class="hint">可修改瀏覽器路徑、UA、尺寸及倍率。瀏覽器 EXE 優先於 channel。</p><textarea v-model="editor" spellcheck="false"></textarea><div class="row"><button class="primary" :disabled="busy" @click="action(async()=>{cfg=await api('config','PUT',JSON.parse(editor));selectAll();profiles=cfg.profiles.map((p:any)=>p.name);await reload();error='設定已儲存'})">驗證並儲存 JSON</button><button @click="exportConfig">匯出 JSON</button><label class="import">匯入 JSON<input type="file" accept=".json" @change="async(e)=>{const file=(e.target as HTMLInputElement).files?.[0];if(file)editor=await file.text()}" /></label></div><p class="hint">輸出位置：工具資料夾內 captures。登入資料：data（含敏感憑證，請勿分享）。</p></section>
</main><div v-if="zoom" class="modal" @click.self="zoom=''"><button @click="zoom=''">關閉 ×</button><a :href="zoom" target="_blank">開啟原圖 ↗</a><img :src="zoom" alt="截圖放大預覽" /></div>
<footer>RWD Capture · Playwright · Chrome / Edge</footer>
</template>



